        setValue(L.MSG_PROMPT_COMPARE_SYSTEM_CHANGED, "Die Systemnachricht unterscheidet sich, daher endet der Cache an ihrem Anfang und die gesamte Geschichte wird erneut gelesen. Sie enthält den Jailbreak, die Hauptvorlage, die Lore, die Zusammenfassungen und die Notizen: Eines davon hat sich zwischen den beiden Anfragen geändert. Verwende „Vor dem Benutzerprompt“ für Lore-Einträge, die sich von Abschnitt zu Abschnitt ändern.");
        setValue(L.MSG_PROMPT_COMPARE_HISTORY_SHIFTED, "Hier erscheint eine Nachricht der Geschichte, die im früheren Prompt an einer anderen Stelle stand: Der Anfang der Geschichte hat sich verschoben (die ältesten Abschnitte passen nicht mehr hinein und wurden weggelassen, oder Abschnitte wurden durch Zusammenfassungen ersetzt). Alles ab diesem Punkt wird erneut gelesen.");
