        setValue(L.MSG_STYLE_PREVIEW_SAMPLE, "# Erstes Kapitel\n\nDer *Regen* hatte seit **drei Tagen** nicht aufgehört, und der Weg zum Hafen war ein Fluss aus Schlamm. „Wir sollten umkehren“, sagte Mara, aber niemand rührte sich.\n\n> Die alten Karten stimmen nicht. Vertrau dem Wasser.\n\n---\n\nDer Morgen kam grau und langsam. Sie zählte die Laternen entlang des Kais, `sieben`, und begann zu gehen.\n\n## Eine kleinere Überschrift\n\nDie Zeilen dieses Absatzes sind lang genug, um zu zeigen, wie der Text umbricht, sich ausrichtet und, wenn die Silbentrennung eingeschaltet ist, ein Wort wie Donaudampfschifffahrtsgesellschaft trennt.");
