        setValue(L.MSG_LORE_USAGE_PART_NOT_RECORDED, "Zur Lore dieses Abschnitts wurde nichts erfasst. Er wurde von Hand getippt, entstand, bevor Marginalia diese Aufzeichnung geführt hat, oder sein Buch hat kein Lorebook.");
