        setValue(L.MSG_LORE_USAGE_HELP, "Ein Eintrag gilt als von einem Abschnitt verwendet, wenn sein Text in den Prompt eingegangen ist, der den Abschnitt geschrieben hat. Die Anteile beziehen sich auf die Abschnitte mit Aufzeichnung. Abschnitte sind wie in der Gliederung der Geschichte nummeriert; „Alle Zweige“ zählt jeden Zweig und jede Variante. Nie verwendete Einträge sind Kandidaten zum Aufräumen oder für einen besseren Filter, immer verwendete Einträge könnten konstante Einträge sein. Ein Eintrag, der jetzt nicht im Lorebook ist, wurde früher verwendet und seitdem gelöscht oder verschoben.");
        setValue(L.MSG_NO_SHARED_LOREBOOKS, "Kein anderer Benutzer teilt ein Lorebook.");
