        setValue(L.MSG_SAVE_OUTDATED_SUMMARIES, "Mit dem Speichern dieser Änderung veralten %d Zusammenfassungen: Sie wurden für den alten Text des Abschnitts geschrieben, und die Generierung verwendet keine veralteten Zusammenfassungen.\n\nZurück zur Bearbeitung, trotzdem speichern oder speichern und die Zusammenfassungen als weiterhin gültig markieren?");
