        setValue(L.MSG_NOTIFICATIONS_INFO, "Teilt dir im Browser, wenn du in einem anderen Tab oder Fenster bist, mit, dass ein Modell fertig ist. Das Kontrollkästchen schaltet Benachrichtigungen für dein Konto ein; jeder Browser, in dem du sie haben möchtest, muss einmalig mit der Schaltfläche registriert werden, weil die Berechtigung zum Browser gehört und nicht zu deinem Konto. Wähle unten, worüber du informiert werden möchtest. Die als automatisch markierten Einträge sind die Läufe, die das Buch von selbst startet (die automatische Annotation); der Eintrag ohne diese Markierung ist der Dialog, den du selbst öffnest.");
