        setValue(L.HELP_LIMIT_EMPTY_UNLIMITED, "Lass ein Limit leer, wenn es keines geben soll. Das Limit, das zuerst erreicht wird, stoppt den Benutzer bis zum nächsten Zurücksetzen.");
