        setValue(L.HELP_ASSISTANT, "Ein Chat, der Fragen zu Marginalia anhand des Handbuchs beantwortet, für die Benutzer mit der Berechtigung „Hilfeassistent“. Wähle eines deiner eigenen Modelle; die Benutzer brauchen kein eigenes.");
        setValue(L.HELP_ASSISTANT_APPLY_LIMITS, "Nur für ein geteiltes Modell: Die Fragen zählen wie jede andere Anfrage an das Modell zum Limit und zur Nutzung des jeweiligen Benutzers. Ohne dies, oder bei einem Modell, das nicht geteilt ist, zahlt der Besitzer des Modells: Nichts wird begrenzt und nichts für den Benutzer gezählt.");
        setValue(L.HELP_ASSISTANT_PROMPT, "Die Anweisungen, die das Modell bei jeder Frage erhält. {{manualIndex}} wird durch die Liste der Seiten des Handbuchs ersetzt. Ein leerer oder mit dem Standard identischer Prompt ist der Standard, folgt also den Änderungen einer neuen Version.");
        setValue(L.HELP_ASSISTANT_INTERACTIONS, "Der Assistent darf sich durch die Oberfläche bewegen, wenn ein Benutzer ihn bittet, ihm etwas zu zeigen: einen Bereich öffnen, einen Tab auswählen oder den Dialog zum Hinzufügen von etwas öffnen (er öffnet nur, nichts wird erstellt). Sonst nichts: Er kann keine anderen Schaltflächen drücken, nichts eintippen, speichern, löschen oder generieren. Das Modell erhält außerdem die Namen der Elemente auf dem Bildschirm mit dem, was sie bieten.");
        setValue(L.HELP_ASSISTANT_ADMIN_DATA, "Der Assistent darf die Daten der Admin-Seite für einen Administrator lesen, der ihn darum bittet: den Zustand der Erweiterungen und ihre Protokolle, die Datenbanksicherungen, was eine Bereinigung entfernen würde, wie viele Benutzer es gibt (keine Namen). Sie werden an das Modell des Assistenten gesendet, das ein externer Anbieter sein kann, und Protokolle können Text enthalten, den Erweiterungen geschrieben haben. Nie für andere Benutzer. Er kann nichts ändern.");
        setValue(L.HELP_COMMAND_TYPE_SLASH, "Gib / und den Namen eines Befehls ein. Trenne Argumente mit Leerzeichen; setze \\ vor ein Leerzeichen oder einen Backslash, die zu einem Argument gehören, oder setze das Argument in \"doppelte Anführungszeichen\".");
        setValue(L.HELP_COMMAND_NO_MATCH, "Kein Befehl passt.");
        setValue(L.HELP_COMMAND_TOO_MANY_ARGUMENTS, "Mehr Argumente, als der Befehl annimmt.");
