        setValue(L.HELP_COMMAND_NON_DESTRUCTIVE, "Dieser Befehl liest nur Daten oder fügt neue hinzu; er ändert nichts, was bereits existiert.");
        setValue(L.HELP_AGENTS_MAX_AGENTS, "Wie viele Agenten der Benutzer haben kann, Klone eingeschlossen. Leer sind fünf, null lässt den Benutzer seine Agenten behalten und ausführen, aber keinen weiteren erstellen oder klonen.");
        setValue(L.HELP_AGENTS_MAX_CONCURRENT_RUNS, "Wie viele Läufe des Benutzers gleichzeitig arbeiten können. Leer ist einer.");
        setValue(L.HELP_AGENTS_RUN_TOKEN_BUDGET, "Die meisten Tokens (gesendet und generiert), die ein Lauf des Benutzers verbrauchen kann. Leer oder null ist kein Limit.");
        setValue(L.HELP_AGENT_SYSTEM_PROMPT, "Was dem Agenten gesagt wird, was er sein soll, vor deinen Anweisungen. Leer folgt dem Standard (dein Standard in den Einstellungen, sonst der des Administrators, sonst der eingebaute), der als Platzhalter angezeigt wird; das Info-Symbol füllt ihn ein, damit du eine Kopie bearbeiten kannst.");
        setValue(L.HELP_AGENT_INSTRUCTIONS, "Deine Anweisungen für den Agenten, bei jedem Lauf seinem Prompt hinzugefügt. Der Agent kann sie lesen, aber nicht ändern. Leer: Es werden die Standardanweisungen aus deinen Einstellungen verwendet.");
        setValue(L.HELP_AGENT_DESTRUCTIVE, "Was geschieht, wenn der Agent einen Befehl ausführen will, der Daten ändert oder entfernt.");
        setValue(L.HELP_AGENT_MAX_ROUNDS, "Die meisten Anfragen an das Modell in einem Lauf. Leer ist kein Limit des Agenten.");
        setValue(L.HELP_AGENT_TOKEN_BUDGET, "Die meisten Tokens, die ein Lauf verbrauchen kann. Leer oder null ist kein Limit des Agenten; das Limit, das dir dein Administrator gegeben hat, gilt trotzdem.");
        setValue(L.HELP_AGENT_CONTEXT_LIMIT, "Limit des Kontexts des Modells in Tokens, niedriger als der Kontext des Modells selbst; ältere Runden werden in dessen Nähe zusammengefasst. Leer ist der Kontext des Modells.");
        setValue(L.HELP_AGENT_SEES_IMAGES, "Hake es an, wenn das Modell Bilder verarbeitet. Der Agent erhält dann ein Tool, das ihm die Bilder seines Arbeitsbereichs zeigt (du legst sie dort mit „Hochladen“ ab). Befehle, die Bilder an ein eigenes Modell senden, wie der Lore Generator, nehmen Bilder aus dem Arbeitsbereich, unabhängig davon, was hier steht.");
        setValue(L.HELP_AGENT_MESSAGE_QUEUED, "Der Agent arbeitet. Deine Nachricht wartet, bis der Agent bereit ist, sie zu lesen.");
        setValue(L.HELP_AGENT_SEND_NOW, "Verwirft, was der Agent in dieser Runde tut, und sendet die Nachricht sofort.");
        setValue(L.HELP_AGENT_DEFAULT_PROMPT_USER, "Wird von deinen Agenten verwendet, die keinen eigenen Systemprompt haben. Leer folgt dem Standard des Administrators, sonst dem eingebauten Prompt.");
        setValue(L.HELP_AGENT_DEFAULT_PROMPT_APP, "Wird von den Agenten verwendet, die keinen eigenen Systemprompt haben und deren Benutzer in den Einstellungen keinen Standardprompt hat. Leer ist der eingebaute Prompt.");
        setValue(L.HELP_AGENTS_MAX_FILE_KB, "Größte Datei, die ein Agent des Benutzers schreiben kann, in KB. Leer sind 1024 (1 MB).");
        setValue(L.HELP_AGENTS_MAX_WORKSPACE_MB, "Wie viel alle Dateien im Arbeitsbereich eines Agenten belegen dürfen, in MB. Leer sind 20.");
        setValue(L.HELP_AGENTS_MAX_WORKSPACE_FILES, "Wie viele Dateien der Arbeitsbereich eines Agenten aufnehmen kann (Ordner sind frei). Leer sind 500.");
        setValue(L.HELP_AGENTS_MAX_COPIES, "Wie viele Arbeitskopien von Büchern die Läufe des Benutzers gleichzeitig behalten können. Ein Lauf, der nicht beendet ist (auch ein pausierter), behält seine Kopie. Leer oder null ist kein Limit außer der Anzahl der Agenten.");
        setValue(L.HELP_AGENT_COMPACTION_PROMPT, "Was der Agent gefragt wird, wenn seine Arbeit verdichtet wird (/compact in der Konsole): Er schreibt die Zusammenfassung, die die früheren Runden ersetzt. Leer folgt dem Standard (dein Standard in den Einstellungen, sonst der des Administrators, sonst der eingebaute), der als Platzhalter angezeigt wird; das Info-Symbol füllt ihn ein, damit du eine Kopie bearbeiten kannst.");
        setValue(L.HELP_AGENT_DEFAULT_COMPACTION_PROMPT_USER, "Wird von deinen Agenten verwendet, die keinen eigenen Verdichtungsprompt haben. Leer folgt dem Standard des Administrators, sonst dem eingebauten Prompt.");
        setValue(L.HELP_AGENT_DEFAULT_COMPACTION_PROMPT_APP, "Wird von den Agenten verwendet, die keinen eigenen Verdichtungsprompt haben und deren Benutzer in den Einstellungen keinen Standard hat. Leer ist der eingebaute Prompt.");
        setValue(L.HELP_AGENT_COMMAND, "Du führst den Befehl aus, nicht der Agent: Ihm wird gesagt, dass du es getan hast und was herauskam. Während der Agent arbeitet, wartet der Befehl auf das Ende seines Zuges.");
        setValue(L.HELP_AGENT_RUN_NOW, "Verwirft, was der Agent in dieser Runde tut, und führt den Befehl sofort aus.");
        setValue(L.HELP_AGENTS_MAX_CHECKPOINT_MB, "Wie viel alle Checkpoints eines Laufs belegen dürfen, in MB; die Wiederherstellungspunkte der Arbeitskopie und ihres Arbeitsbereichs, die vom Agenten erstellten und die automatischen. Leer sind 100.");
        setValue(L.HELP_AGENT_CHECKPOINTS, "Wiederherstellungspunkte der Arbeitskopie des Buchs und des Arbeitsbereichs. Der Lauf erstellt einen beim Start und einen vor den Runden, die etwas ändern (die letzten fünf werden behalten); der Agent kann eigene speichern. Sie teilen sich ein vom Administrator festgelegtes Kontingent. „Wiederherstellen“ bringt das Buch und den Arbeitsbereich zurück; „Zurückspulen“ bringt zusätzlich die Unterhaltung an die Stelle zurück, an der der Checkpoint erstellt wurde, damit der Agent sich nicht an Arbeit erinnert, die nicht mehr im Buch ist (ein pausierter oder gestoppter Lauf).");
        setValue(L.HELP_MERGE, "Der Agent hat an einer Kopie des Buchs gearbeitet. Wähle, was übernommen werden soll, das Buch wird zuvor gespeichert. Der Text rechts ist das, was geschrieben wird: Bearbeite ihn, um ihn zu ändern. Ein Konflikt ist ein Text, den sowohl du als auch der Agent geändert haben.");
        setValue(L.HELP_COMMAND_PRESETS, "Rollen: Der Prüfer liest nur; der Lore-Hüter schreibt auch Lorebooks; der Lektor überarbeitet zusätzlich den Text, die Zusammenfassungen und die Buchinfo; der Entwerfer fügt außerdem neue Abschnitte hinzu und lässt das Modell den nächsten Zug schreiben. Keiner von ihnen kann Daten entfernen.");
        setValue(L.HELP_AGENT_PAUSE_NOW, "Bricht die laufende Anfrage an das Modell und den laufenden Aufruf ab und pausiert sofort. Was sie getan hätten, geht verloren; ein Aufruf, der sich nicht stoppen lässt, kann noch zu Ende laufen, der Agent prüft den Zustand, wenn er weitermacht.");
        setValue(L.HELP_AGENT_DEFAULT_INSTRUCTIONS_USER, "Anweisungen für die deiner Agenten, die keine eigenen haben, bei jedem Lauf ihrem Prompt hinzugefügt. Leer bedeutet keine Anweisungen.");
        setValue(L.HELP_AGENT_AUTO_COMPACT, "Wenn der Kontext des Modells diesen Anteil seines Limits überschreitet und der Agent seine Arbeit nicht selbst verdichtet hat, fasst der Lauf die früheren Runden zusammen. Leer ist %d. Null verdichtet nie (der Lauf stoppt dann, wenn der Kontext voll ist). Sonst %d bis 99.");
        setValue(L.HELP_AGENT_USE_OWN_MODEL, "An: Was der Agent per Befehl schreiben lässt (der nächste Zug, Zusammenfassungen und die Befehle von Erweiterungen wie dem Lore Generator), verwendet das obige Modell, unabhängig vom Modell des Buchs. Aus: Es verwendet das Modell des Buchs, sodass du Modelle mischen kannst: eines, das nachdenkt, und eines, das schreibt. Ein Befehl kann weiterhin ein anderes Modellprofil des Agenten nennen.");
        setValue(L.HELP_AGENT_WEBHOOK_URL, "Wenn ein Agent etwas fragt, auf dich wartet, fertig wird oder fehlschlägt und du die Anwendung nicht geöffnet hast, sendet der Server eine kurze Nachricht an diese Adresse: zum Beispiel dein ntfy-Topic (https://ntfy.sh/dein-topic), eine Gotify-Nachrichten-URL oder ein Discord-Webhook. Jeder, der die Adresse kennt, kann die Nachrichten lesen. Leer sendet nichts.");
        setValue(L.HELP_AGENT_WEBHOOKS_ALLOWED, "Der Server ruft die Adresse auf, die ein Benutzer in seinen Einstellungen eingetragen hat. Schalte dies aus, wo das nicht akzeptabel ist (zum Beispiel, wenn der Server ein Netzwerk erreichen kann, das die Benutzer nicht erreichen sollen).");
        setValue(L.HELP_AGENTS_MAX_CONCURRENCY, "Wie viele Anfragen an das Modell ein Lauf gleichzeitig in der Luft haben kann, der Agent und seine Unteragenten zusammen. Bei einer wartet der Agent (ist geparkt), während sein Unteragent das Modell anfragt. Leer ist 1.");
        setValue(L.HELP_AGENT_MAX_SUBAGENTS, "Wie viele Unteragenten der Agent gleichzeitig arbeiten lassen kann. Null oder leer ist keiner: Der Agent erhält keine Tools, um sie zu starten. Bei einem wartet das Starten eines Unteragenten, bis dieser fertig ist; bei mehreren kehrt der Aufruf sofort zurück, bis das Limit erreicht ist, und wartet dann auf das Ende eines. Unteragenten können keine Unteragenten starten, und die Anfragen aller zählen in den Budgets des Laufs.");
        setValue(L.HELP_AGENT_CANCEL_QUEUED, "Nimmt die Nachricht oder den Befehl zurück: Der Agent erhält sie nicht.");
        setValue(L.HELP_AGENT_CONTEXT, "Was das Modell mit seiner nächsten Anfrage liest, Teil für Teil: die Systemnachricht, die Tool-Definitionen und die Unterhaltung. Nichts wird abgeschnitten; lade es als Markdown herunter, um es in einem Editor zu lesen. Die Token-Zahlen der Teile sind Schätzungen, die Linie im Diagramm ist das, was das Modell gemeldet hat.");
        setValue(L.HELP_AGENT_ROLLBACK_MESSAGE, "In der Unterhaltung auf den Stand vor dieser Nachricht zurückgehen: Der Agent vergisst sie und alles danach, und die Arbeitskopie und der Arbeitsbereich kehren zum nächstgelegenen Checkpoint davor zurück.");
        setValue(L.HELP_AGENT_COPY, "Die Kopie des Buchs, an der der Agent arbeitet, zum Lesen: Nichts hier ändert sie. Die Geschichte wird Zweig für Zweig gezeigt, die Lorebooks mit ihren Einträgen. Sie wird gelesen, wenn dieser Tab angezeigt wird oder du auf „Aktualisieren“ klickst.");
        setValue(L.HELP_AGENT_SUBAGENTS, "Was den Unteragenten des Laufs gesagt wurde, was sie gesagt und aufgerufen haben und wie sie geendet haben. Es folgt dem Lauf, während er arbeitet; die eines älteren Laufs liest man, indem man diesen Lauf unter „Läufe“ wählt.");
        setValue(L.HELP_AGENT_COMMAND_TOKENS, "Was die Definition des Befehls (sein Name, seine Beschreibung und seine Parameter) bei jeder Anfrage des Agenten hinzufügt, als Schätzung. Eine kleinere Auswahl an Befehlen lässt mehr Platz für die Arbeit.");
        setValue(L.HELP_MULTI_TAG, "Wähle einen Tag (oder tippe einen neuen) und wende ihn dann auf die Elemente einzeln an oder entferne ihn, oder auf alle markierten unten. Die Elemente, die den Tag haben, werden zuerst aufgelistet und zeigen ihn markiert. Elemente, an denen ein Agent arbeitet, sind ausgegraut und können nicht geändert werden.");
        setValue(L.HELP_AGENT_DIAGNOSTICS, "Was der Lauf getan hat, gezählt aus seinem Verlauf: die Aufrufe nach Tool mit ihren Fehlern, Ergebnissen und Zeiten, die Runden, in denen ein Tool nach dem anderen aufgerufen wurde, die größten Ergebnisse, die langsamsten Runden, der Kontext und die Unteragenten. Es funktioniert für jeden Lauf, auch für einen alten. Lade es als Markdown oder JSON herunter, um es in einem Editor zu lesen oder jemandem zu geben.");
        setValue(L.HELP_COMMAND_BATCH_POLICY, "Wie der Befehl unter den Aufrufen einer Antwort verwendet wird. Zusammen: Er darf mit anderen aufgerufen werden. Allein: Er wird in einer eigenen Antwort aufgerufen, weil er lang oder teuer ist (zum Beispiel ruft er ein Modell auf) oder sein Ergebnis zuerst gelesen werden soll. Der Agent kann so eingestellt werden, dass er dies ignoriert.");
        setValue(L.HELP_AGENT_BATCH_MODE, "Wie viele Aufrufe einer Antwort des Agenten ausgeführt werden. Alle zusammen: jeder Aufruf, egal was die Stapelrichtlinien der Befehle sagen (am schnellsten). Zusammen, als „Allein“ markierte Befehle für sich: Die Aufrufe werden zusammen ausgeführt, aber ein als „Allein“ markierter Befehl wird in einer eigenen Antwort ausgeführt. Ein Aufruf je Antwort: Nur der erste Aufruf wird ausgeführt und der Agent schreibt den nächsten, nachdem er das Ergebnis gelesen hat (am langsamsten, jeder Aufruf ist eine Runde mit dem Nachdenken des Modells, aber er kann auf jedes Ergebnis reagieren). Ein Fehler beendet die Antwort in jedem Modus: Die Aufrufe nach dem fehlgeschlagenen werden nicht ausgeführt.");
        setValue(L.HELP_LOREBOOK_MASS_EDIT, "Jeder Eintrag des Lorebooks und seiner Unterbücher, nach Reihenfolge. Ändere das Kontrollkästchen „Aktiviert“, den Namen, die Reihenfolge und die Tags eines Eintrags direkt, der Text wird gekürzt angezeigt (öffne den Eintrag im Lorebook, um ihn zu lesen oder zu bearbeiten). Verschiebe einen Eintrag in das Lorebook selbst oder in eines seiner Unterbücher mit dem Lorebook-Feld seiner Zeile, oder verschiebe alle markierten Einträge auf einmal mit dem Feld unten. Einträge eines Lorebooks, an dem ein Agent arbeitet, sind ausgegraut und können nicht geändert werden.");
        setValue(L.HELP_STORY_PARTS_LIMIT, "Die Geschichte und der Leser halten nur so viele Abschnitte des Buchs geladen: Die Geschichte beginnt mit den letzten, der Leser dort, wo du zuletzt in diesem Browser aufgehört hast zu lesen (oder bei den ersten). Die Abschnitte davor und danach werden beim Scrollen nachgeladen, und die weit von dir entfernten werden wieder verworfen. Leer lädt alle Abschnitte auf einmal.");
        setValue(L.HELP_AGENT_MODELS, "Andere Modelle, auf denen der Agent einen Unteragenten starten kann: Er wählt eines mit dem Profil von spawn_agent anhand der Rolle und der Beschreibung. Die Befehle jedes Modells sind höchstens die, die der Agent verwenden darf.");
        setValue(L.HELP_AGENT_SELF_SUBAGENT, "Aus: Der Agent kann Unteragenten nur auf den anderen Modellen der Liste starten. Ohne weiteres Modell erhält der Agent keine Tools für Unteragenten.");
        setValue(L.HELP_AGENT_MODEL_COMMANDS, "Aus: Ein Unteragent auf diesem Modell hat die Befehle des Agenten. An: nur die angehakten Befehle, und davon nur die, die der Agent verwenden darf. Die Tools für Dateien sind keine Befehle, ein Unteragent hat sie immer.");
        setValue(L.HELP_AGENT_MODEL_TOOLS, "Aus: Das Modell antwortet nur mit Text, es erhält keine Befehle und keine Tools.");
        setValue(L.HELP_AGENT_RESUME_NOTE, "Der Agent liest dies zuerst, wenn er weitermacht, nach dem Bericht über die Änderungen, die du am Buch vorgenommen hast, falls es welche gibt. Es funktioniert für jeden Lauf, auch für einen, der nicht auf deine Nachrichten wartet.");
        setValue(L.HELP_AGENT_LANGUAGE, "Die Sprache von allem, was der Agent liest: die Beschreibungen seiner Befehle, ihre Ergebnisse und Fehler. Sie hat nichts mit der Sprache des Buchs zu tun: Der Agent schreibt das Buch in der Sprache des Buchs, unabhängig davon, was eingestellt ist. Befehle und ihre Parameter sind in jeder Sprache auf Englisch, daher ist Englisch die zuverlässigste Wahl, besonders für kleine Modelle. Die Liste enthält die installierten Sprachen; ein Lauf behält die Sprache, mit der er gestartet wurde.");
        setValue(L.HELP_JSON_MERGE, "Die Daten des Agenten, des Buchs jetzt und des Starts des Laufs übereinandergelegt. Wähle eine Stelle und übernimm die Daten eines davon, lass sie weg oder setze sie aus den Stellen darin zusammen. Was nur eine Seite geändert hat, wird von ihr übernommen, was beide geändert haben, wird Stelle für Stelle zusammengesetzt, und eine Stelle, die beide auf dieselbe Weise geändert haben, ist ein Konflikt: Die Version des Agenten wird übernommen, bis du entscheidest. Öffne eine Stelle, um nur mit ihr zu arbeiten. Die Elemente einer Liste werden nach dem zugeordnet, was sie sind (dieselben Daten, dieselbe ID oder derselbe Name, die ähnlich aussehenden); wenn die Vermutung falsch ist, teile ein Element auf oder ordne es einem anderen zu. In der Textansicht kannst du die Daten des Agenten für die geöffnete Stelle von Hand schreiben; sie werden geprüft, wenn du zum Baum zurückkehrst.");
        setValue(L.HELP_NOTIFICATIONS_ALLOW_LOCAL, "Nur mit erteilter Berechtigung. Der Server sendet dann auch Nachrichten an localhost, an die privaten Netzwerke, die er erreichen kann, und an Link-Local-Adressen (zum Beispiel ein ntfy oder Gotify in deinem eigenen Netzwerk). Ohne sie werden nur öffentliche Adressen aufgerufen. Administratoren sind nicht eingeschränkt.");
        setValue(L.HELP_COMMAND_SEARCH, "Wörter aus dem Namen oder der Beschreibung eines Befehls, in beliebiger Reihenfolge. Die Tabelle zeigt nur die Befehle, die alle enthalten; die Auswahl oben gilt weiterhin für alle Befehle.");
        setValue(L.HELP_KEYBOARD_SHORTCUTS, "Klicke auf „Aufnehmen“ und drücke die neue Tastenkombination. Eine Taste ohne Strg, Alt oder Meta funktioniert nur, wenn kein Textfeld den Fokus hat. Die Tastenkürzel funktionieren im Tab „Geschichte“ eines geöffneten Buchs.");
        setValue(L.HELP_ST_MERGE_TURNS, "Die Nachricht des Benutzers wird zu den Anweisungen des Abschnitts, der aus der darauf folgenden Antwort entsteht. Ohne dies ist jede Nachricht ein eigener Abschnitt.");
        setValue(L.HELP_AI_TOKENIZER, "Wie die Tokens dieser KI gezählt werden. „Automatisch“ probiert die Tokenizer-Endpunkte des Servers (OpenAI, llama.cpp, LiteLLM) und fällt auf eine lokale Schätzung zurück; wähle einen, um nur diesen zu verwenden. Ein Tokenizer aus einem Plugin erhält den Endpunkt, das Modell und den Text, und nur, wenn er hier gewählt ist.");
        setValue(L.HELP_SCAN_DEPTH, "Wie oft der Inhalt der verwendeten Einträge nach den Filtern der anderen Einträge durchsucht wird (0 = nie). Es gilt für dieses Lorebook und für seine Unter-Lorebooks, die keine eigene Scan-Tiefe haben.");
        setValue(L.HELP_PREVENT_RECURSION, "Wörter im Inhalt dieses Eintrags aktivieren keine anderen Einträge.");
        setValue(L.HELP_ACTIVATION_PREVIEW, "Zeigt, welche Einträge dieses Lorebooks und seiner Unterbücher für einen Zug mit diesem Text verwendet würden und warum, mit der Scan-Tiefe dieses Lorebooks. Bei einer echten Generierung können Erweiterungen das Ergebnis noch ändern. Einträge, die auch in die Abschnitte der Geschichte schauen, verwenden die neuesten Abschnitte des gewählten Buchs.");
        setValue(L.HELP_ACTIVATION_CONTEXT, "Wo der Filter gesucht wird: nur in den Anweisungen des Zugs oder in den Anweisungen und den neuesten Abschnitten der Geschichte.");
        setValue(L.HELP_ACTIVATION_PARTS, "Wie viele der neuesten Abschnitte der Geschichte zusammen mit den Anweisungen durchsucht werden (mindestens 1).");
        setValue(L.HELP_PART_SYSTEM_PROMPT, "Die Systemnachricht. Die Geschichte vor dem Abschnitt wird danach als frühere Nachrichten der Unterhaltung gesendet, also behalte hier, was von einer Anfrage zur nächsten gleich bleibt: Ein Server kann dann wiederverwenden, was er schon gelesen hat.");
        setValue(L.HELP_PART_LAST_PROMPT, "Die letzte Nachricht des Benutzers: was sich von einer Anfrage zur nächsten ändert (die Geschichte nach dem Abschnitt, der Abschnitt selbst, seine Notizen, die Aufgabe).");
        setValue(L.HELP_MASS_CHANGE_MODEL_PROTOCOL, "Wähle das Modell und/oder das Protokoll, das auf die Bücher angewendet werden soll, und hake die Bücher an. Eine leere Auswahl bedeutet „nicht ersetzen“: Dieser Teil des Buchs bleibt, wie er ist. Bücher, an denen ein Agent arbeitet, sind ausgegraut und können nicht geändert werden.");
        setValue(L.HELP_MASS_CHANGE_LANGUAGE, "Wähle die Sprache, die auf die Bücher angewendet werden soll, und hake die Bücher an. Bücher, an denen ein Agent arbeitet, sind ausgegraut und können nicht geändert werden.");
        setValue(L.HELP_ORGANISE, "Links / Rechts / Tab: anderer Bereich. Enter: einen Ordner öffnen. Rücktaste: nach oben. Leertaste oder Einfg: markieren. Die Tasten der Schaltflächen können in den Einstellungen geändert werden (Tastenbelegung).");
        setValue(L.HELP_FOLDER_SETTINGS, "Die Bücher in diesem Ordner und in den Ordnern darunter verwenden diese Einstellungen, sofern sie keine eigenen festlegen. Ein leeres Feld wird vom übergeordneten Ordner geerbt, dann aus deinen Einstellungen.");
        setValue(L.HELP_MASS_RENAME, "Wähle, wie die Bücher umbenannt werden sollen, und hake die Bücher an: Die Spalte „Neuer Name“ zeigt das Ergebnis. Eine Nummerierung zählt die markierten Bücher in der Reihenfolge der Liste; im Muster ist {name} der aktuelle Name und {n} die Nummer. Bücher, an denen ein Agent arbeitet, sind ausgegraut und können nicht umbenannt werden.");
        setValue(L.HELP_HISTORY_MAX_VERSIONS, "Wie viele Versionen eines Abschnitts der Verlauf aufbewahrt (die im Papierkorb zählen mit). Leer: Diese Ebene setzt kein Limit. 0 bewahrt keinen Verlauf auf. Es gilt das strengste Limit aus Buch, seinen Ordnern, deinen Einstellungen und dem Limit des Administrators. Die erste generierte Version und die gespeicherten werden zusätzlich aufbewahrt.");
        setValue(L.HELP_VERSION_HISTORY_PERMISSION, "Die meisten Versionen eines Abschnitts, die der Verlauf der Bücher des Benutzers aufbewahrt. Leer: kein Limit vom Administrator. Ein Benutzer ohne diese Berechtigung hat 50; eine nicht erteilte Berechtigung bewahrt keinen Verlauf auf.");
        setValue(L.HELP_DAILY_GOAL, "Die Ziele des Kalenders der Statistik, über alle Bücher: die Wörter, die du selbst schreibst (nicht die generierten), und die Minuten, die du an einem Tag bearbeitest. Ein Tag, der jedes festgelegte Ziel erreicht, zählt für die Zielserie. Leer ist kein Ziel.");
        setValue(L.HELP_ACTIVATION_RANGE, "Der Eintrag wird nur für die Züge verwendet, die einen Abschnitt von dieser Nummer bis zu dieser erstellen (die Nummern der Gliederung der Geschichte, beide eingeschlossen, der erste Abschnitt ist 1). Lass ein Feld leer für kein Limit. Eine Variante oder eine Neugenerierung zählt als der Abschnitt, den sie ersetzt. Ein Zug, dessen Vorschau ohne Buch erfolgt, hat keine Nummer, der Bereich wird nicht geprüft.");
        setValue(L.HELP_STYLES, "Stile ändern, wie der Text der Abschnitte in der Geschichte und im Leser aussieht. Eingebaute Stile können nicht geändert werden: Dupliziere einen, um einen eigenen Stil zu erstellen. Der Standardstil wird von den Büchern verwendet, die im Menü „Stile für Text ändern“ ihrer Geschichte keinen gewählt haben.");
        setValue(L.HELP_STYLE_VALUES, "Ein beliebiger CSS-Wert (zum Beispiel 1.1rem, #336699 oder var(--lumo-body-text-color)). Leer behält das Aussehen der Anwendung.");
        setValue(L.HELP_STYLE_CUSTOM_CSS, "CSS, das nach den Optionen im Geltungsbereich des Stils hinzugefügt wird. Schreibe Regeln für den Text der Abschnitte, zum Beispiel \".chat-message-markdown p { text-indent: 1.5em !important; }\", oder Deklarationen, die für das ganze Element gelten.");
        setValue(L.HELP_EXPORT_SETTINGS, "Jedes Format wird im hier gewählten Stil und mit deiner Version seiner Vorlagen exportiert, bis du im Export-Dialog etwas anderes wählst. Stile für Exporte werden im Tab „Stile“ erstellt („Für Exporte“ anhaken). Lass eine Vorlage leer, um die Standardvorlage zu verwenden.");
        setValue(L.HELP_IMAGE_LAYOUT, "Der Viewer und die Exporte platzieren das Bild so. Der Editor der Geschichte listet die Bilder nach dem Text auf; „Vorschau wie im Viewer“ zeigt das Ergebnis.");
        setValue(L.HELP_LOREBOOK_SHARED, "Andere Benutzer sehen dieses Lorebook mit seinen geteilten Unter-Lorebooks unter „Von anderem Benutzer importieren“ und können eine Kopie davon importieren. Sie können deines nicht ändern.");
        setValue(L.HELP_PROTOCOL_SHARED, "Andere Benutzer sehen dieses Protokoll unter „Von anderem Benutzer importieren“ und können eine Kopie davon importieren. Sie können deines nicht ändern.");
        setValue(L.HELP_MATCH_BY_POSITION, "Zusammenfassungen werden den Abschnitten über die ID des Abschnitts zugeordnet. Hake dies für eine Datei aus einem anderen Buch an (eine Kopie hat andere IDs): Eine Zusammenfassung, deren Abschnitt nicht in diesem Zweig ist, geht an die Zusammenfassung an derselben Position.");
        setValue(L.HELP_ANNOTATE_INSTRUCTIONS, "Worauf das Modell achtet, wenn es einen Abschnitt kommentiert, zum Beispiel: Kontinuitätsfehler, schwache Dialoge markieren. Leer ist die Standardaufgabe des Annotationsprompts. Das Fenster „Mit KI kommentieren“ beginnt mit diesem Text.");
        setValue(L.HELP_ACTIVATION_CONDITION, "Eine Vorlage, geschrieben wie der Inhalt (Makros und Handlebars), die für den Zug mit der Erzählperspektive, den anwesenden Figuren, den Anweisungen und den Variablen gerendert wird. Der Eintrag wird nur verwendet, wenn das Ergebnis wahr ist: alles außer leer, 0, false, no oder off. Eine Bedingung, die nicht gerendert werden kann (ein Fehler, ein nicht existierender Name, zu viel Zeit), gilt als falsch, und die Aktivierungsvorschau nennt den Grund. Sie wird vor dem Filter geprüft, auch für Einträge, die über den Inhalt anderer Einträge gefunden werden. Befehle, die nur lesen, können verwendet werden, Variablen werden nicht geändert. Leer lassen für keine Bedingung.");
        setValue(L.HELP_REASONING_PASSTHROUGH, "Ob das Denken des Modells in der nächsten Anfrage an es zurückgeht (als reasoning_content). Zwischen Tool-Aufrufen: nur solange die Tool-Aufrufe einer Antwort andauern, wie es Gemma 4 erwartet. Immer: auch bei jeder früheren Antwort, die es hat. Die meisten Modelle und Server wollen „Keines“.");
        setValue(L.HELP_RECURSION_ONLY, "Der Eintrag wird nie wegen der Anweisungen oder der Geschichte des Zugs verwendet. Er wird nur verwendet, wenn sein Filter im Inhalt eines anderen verwendeten Eintrags gefunden wird (erfordert eine Scan-Tiefe über 0 und einen Filter).");
        setValue(L.HELP_ACTIVATION_SUMMARIES, "Der Filter wird auch in den Zusammenfassungen der bisherigen Geschichte gesucht (denen, die der Prompt verwenden würde).");
        setValue(L.HELP_OWN_SCAN_DEPTH, "Die Scan-Tiefe der Einträge dieses Lorebooks, solange es ein Unter-Lorebook eines anderen ist (0 = nie über den Inhalt anderer Einträge gefunden). Leer = die Scan-Tiefe des Lorebooks, das das Buch verwendet.");
        setValue(L.HELP_AUTHORSHIP, "Ermittelt aus dem Verlauf jedes Abschnitts des aktiven Zweigs: die Wörter, die ein Modell oder ein Agent geschrieben hat, und die Wörter, die du getippt oder geändert hast. Es liest alle Versionen, daher dauert es bei einem langen Buch eine Weile.");
        setValue(L.HELP_INCLUDE_AUTHORSHIP, "Fügt am Ende des exportierten Textes eine Angabe hinzu: wie viele Wörter du geschrieben hast und wie viele ein Modell generiert hat. Der Wortlaut ist eine Vorlage in den Export-Einstellungen.");
        setValue(L.HELP_STATISTICS_RECORD, "Wenn aus, werden für deine Bücher keine neuen Zählungen, Zeiten oder Größen erfasst. Was erfasst wurde, bleibt, bis du es löschst. Ein Administrator kann die Erfassung für alle ausgeschaltet haben.");
        setValue(L.HELP_STATISTICS_KEEP_MONTHS, "Ältere Tage werden einmal täglich endgültig gelöscht. 0 behält alles. Der Administrator kann weniger aufbewahren.");
        setValue(L.HELP_STATISTICS_ADMIN, "Die Statistik hält fest, wann Benutzer an ihren Büchern gearbeitet haben, wie lange, sowie die Namen und Ordner ihrer Bücher, auch gelöschter. Schalte die Erfassung aus oder begrenze, wie lange sie aufbewahrt wird; Benutzer können für sich selbst eine kürzere Zeit wählen.");
        setValue(L.HELP_STATISTICS_KEEP_MONTHS_INSTANCE, "Ältere Tage werden einmal täglich aus der Statistik jedes Benutzers endgültig gelöscht. 0 behält alles. Ein Benutzer kann für sich selbst eine kürzere Zeit wählen.");
        setValue(L.HELP_JOBS_ADMIN, "Jeder Job, der mit einer externen KI spricht (eine Generierung, eine Zusammenfassung, ein Hörbuchkapitel, ein Bild), wird hier mit dem Benutzer, seinem Start und Ende und jedem Aufruf, den er an ein Modell oder ein Sprach- oder Bild-Backend gemacht hat, protokolliert. Es werden nur Metadaten aufbewahrt, nie der Text. Nichts wird automatisch gelöscht: Setze den Filter und lösche die passenden Jobs.");
        setValue(L.HELP_PLANNER_IMPORT_FROM_BRANCH, "Fügt die Zugdetails der Abschnitte des aktuellen Zweigs als Szenen hinzu, um eine Neufassung der Geschichte zu planen");
        setValue(L.HELP_WORDS_PER_PART, "Der Text wird zwischen Absätzen in Abschnitte von etwa dieser Wortzahl geteilt. Ein Abschnitt enthält nie Text aus zwei Kapiteln, und was am Ende eines Kapitels übrig bliebe, wenn es weniger als die Hälfte dieser Zahl ist, bleibt beim Abschnitt davor.");
        setValue(L.HELP_CHAPTER_HEADING_LEVEL, "Überschriften dieser Ebene und der darüberliegenden beginnen ein Kapitel, und jedes Kapitel beginnt mit seiner Überschrift. Tiefere Überschriften bleiben im Text.");
        setValue(L.HELP_IMPORT_PLACE, "Die Abschnitte werden als von dir geschrieben hinzugefügt. Was auf die Stelle folgt, rückt hinter sie, daher veralten die Zusammenfassungen, die die Stelle abdecken.");
        setValue(L.HELP_CREATE_SUMMARIES, "Schreibt eine Zusammenfassung für jeden Block der Geschichte nach der neuesten Zusammenfassung, den ältesten Block zuerst. Die vorhandenen Zusammenfassungen werden nicht angetastet. Ein Block endet dort, wo es die Einstellung sagt, und wird nie länger, als das Modell lesen kann.");
        setValue(L.HELP_SUMMARY_CHAPTERS, "Ein Kapitel ist ein Abschnitt, der mit einer Überschrift beginnt. Ein Kapitel, das beginnt, wenn die bisherige Zusammenfassung weniger Tokens als das Minimum hat, beendet sie nicht: Ein kurzes Kapitel wird zusammen mit dem nächsten zusammengefasst.");
        setValue(L.HELP_AFTER_IMPORT, "Die Abschnitte sind im Buch. Zwei Dinge erleichtern das Weiterschreiben an einer langen Geschichte: Zusammenfassungen des Importierten und ein Lorebook mit ihren Figuren und Orten. Erstelle zuerst die Zusammenfassungen: Ein Agent sperrt das Buch, solange er arbeitet.");
        setValue(L.HELP_REDRAFT_LENGTH_PROMPT, "Reiner Text, der deinen Anweisungen hinzugefügt wird, wenn die Überarbeitung kürzer (länger) sein soll. Es ist keine Vorlage. Leer ist der eingebaute Text.");
        setValue(L.HELP_UPDATE, "Aktualisiert eine Docker-Installation aus ihrem Git-Checkout, ohne sich am Server anzumelden: Die neueste Version des Zweigs wird geholt und mit den Plugins gebaut, und Marginalia wird neu gestartet.");
        setValue(L.HELP_AI_CONNECTIONS, "Wie viele Anfragen gleichzeitig zu diesem Modell unterwegs sein dürfen: jede Anfrage, von jedem Benutzer und jeder Art (deine Generierung, eine Nebenabfrage, ein Agent, ein Plugin). Die anderen warten in der Reihenfolge, in der sie kamen, auf ihren Zug. 1 für einen Server mit einem Slot (zum Beispiel eine GPU); ein Cloud-Modell, das mehrere Anfragen gleichzeitig beantwortet, kann mehr haben.");
        setValue(L.HELP_ENTRY_LINKS, "Strg+Klick (Cmd+Klick auf dem Mac) auf den Namen oder ein Schlüsselwort eines anderen Eintrags im Inhalt öffnet ihn, mit Umschalt in einem neuen Tab. Die hier aufgelisteten Einträge nennen diesen in ihrem Inhalt: Klicken zum Öffnen, Umschalt+Klick für einen neuen Tab.");
        setValue(L.HELP_SEND_LORE_IMAGES, "Die Bilder im Inhalt der Lorebook-Einträge, die der Zug verwendet, zusammen mit der Lore senden. Nur für ein Modell, das Bilder akzeptiert: Ein Modell ohne Bildverständnis lehnt die Anfrage ab.");
        setValue(L.HELP_LORE_IMAGES_IN_SYSTEM, "Die Bilder des Lore-Blocks in die Systemnachricht selbst legen statt in eine eigene Nachricht danach. Nur für einen Server und ein Chat-Template, die dort Bilder annehmen; die meisten tun das nicht.");
        setValue(L.HELP_PROMPT_LANGUAGE, "Die Sprache der eingebauten Prompts (Generierung, Zusammenfassungen, Überarbeitung, Anmerkungen, Impersonate, Agenten) und der Prompts der Plugins. Die Prompts, die du selbst geschrieben hast, bleiben, wie sie sind; die Sprache der Oberfläche wird separat festgelegt.");
